import { readFileSync } from "node:fs";
import { mkdtemp, writeFile, rm } from "node:fs/promises";
import { spawn } from "node:child_process";
import { createServer } from "node:http";
import { join } from "node:path";
import { tmpdir } from "node:os";
import vm from "node:vm";
import test from "node:test";
const raw = readFileSync("tests/fleet-connector-install.test.mjs", "utf8");
const body = raw.slice(raw.indexOf('"'"'test("fifty cross-process rotations'"'"'));
const childSource = vm.runInNewContext(body.match(/const childSource = (`[\s\S]*?`);/u)[1]);
test("fixture child exits on parent disconnect while a real HTTP response is held", { timeout: 20000 }, async t => {
  const root = await mkdtemp(join(tmpdir(), "rotation-parent-probe-"));
  const configPath = join(root, "bot.json");
  let started;
  const requestStarted = new Promise(resolve => { started = resolve; });
  const server = createServer(request => { request.resume(); started(); });
  await new Promise((resolve, reject) => { server.once("error", reject); server.listen(0, "127.0.0.1", resolve); });
  const port = server.address().port;
  await writeFile(configPath, JSON.stringify({ schema: "control-room.fleet-connector/v1", server: `http://127.0.0.1:${port}`,
    workerId: `fleet-worker:${"a".repeat(32)}`, secret: `crf_${"R".repeat(43)}`, credentialExpiresAt: "2026-01-01T00:00:00.000Z" }), { mode: 0o600 });
  const child = spawn(process.execPath, ["--input-type=module", "--eval", childSource, configPath],
    { stdio: ["ignore", "pipe", "pipe", "ipc"] });
  child.stdout.resume(); child.stderr.resume();
  child.on("message", message => { if (message === "observed") child.send("admit"); });
  child.on("disconnect", () => t.diagnostic("parent IPC disconnect observed"));
  child.on("exit", (code, sig) => t.diagnostic(`child exit observed code=${code} signal=${sig}`));
  child.on("close", () => t.diagnostic("child close observed"));
  const closed = new Promise(resolve => child.once("close", () => resolve(true)));
  const exited = new Promise(resolve => child.once("exit", () => resolve(true)));
  let timer, drainTimer;
  try {
    await new Promise((resolve, reject) => { child.once("message", resolve); child.once("error", reject); });
    child.send("rotate");
    await requestStarted;
    const start = performance.now();
    child.disconnect();
    const stopped = await Promise.race([exited, new Promise(resolve => { timer = setTimeout(() => resolve(false), 10000); })]);
    t.diagnostic(`observed real HTTP request; child stopped=${stopped}; disconnect elapsed=${Math.round(performance.now() - start)}ms`);
    assert.equal(stopped, true, "parent disconnect must stop a child before its held HTTP request is answered");
  } finally {
    clearTimeout(timer);
    if (child.exitCode === null && child.signalCode === null) child.kill("SIGKILL");
    server.closeAllConnections();
    await exited;
    await Promise.race([closed, new Promise(resolve => { drainTimer = setTimeout(resolve, 2000); })]);
    clearTimeout(drainTimer);
    child.stdout.destroy(); child.stderr.destroy();
    await new Promise(resolve => server.close(resolve));
    await rm(root, { recursive: true, force: true });
  }
});
'

